"""Load a .pkl model and run predictions."""
import joblib
import json
import traceback
import numpy as np
from typing import Any, Optional
from pathlib import Path


class ModelPredictor:
    def __init__(self, pkl_path: str, task_type: str = 'unknown'):
        self.pkl_path = pkl_path
        self.task_type = task_type
        self._model = None
        self._class_labels: Optional[list] = None
        self._feature_count: Optional[int] = None

    def load(self) -> 'ModelPredictor':
        try:
            self._model = joblib.load(self.pkl_path)
            # Try to extract metadata if stored alongside
            meta_path = Path(self.pkl_path).with_suffix('.meta.json')
            if meta_path.exists():
                with open(meta_path) as f:
                    meta = json.load(f)
                    self._class_labels = meta.get('class_labels')
                    self._feature_count = meta.get('feature_count')
        except Exception as e:
            raise RuntimeError(f"Failed to load model from {self.pkl_path}: {e}")
        return self

    @property
    def model(self):
        return self._model

    @property
    def class_labels(self) -> Optional[list]:
        return self._class_labels

    @property
    def feature_count(self) -> Optional[int]:
        return self._feature_count

    def predict(self, data: Any) -> dict[str, Any]:
        """Run prediction. Returns dict with result, raw_output, metadata."""
        if self._model is None:
            raise RuntimeError("Model not loaded. Call load() first.")

        try:
            # Normalize input
            if isinstance(data, list):
                if isinstance(data[0], list):
                    X = np.array(data)
                else:
                    X = np.array(data).reshape(1, -1)
            else:
                X = data

            # Auto-detect sklearn estimator type if unknown
            if self.task_type == 'unknown' and hasattr(self._model, 'predict'):
                self.task_type = self._detect_task_type()

            # Run prediction
            result = self._model.predict(X)

            # Format output
            output = self._format_output(result)

            return {
                'success': True,
                'prediction': output['prediction'],
                'raw_output': output['raw'],
                'task_type': self.task_type,
                'class_labels': self._class_labels,
            }
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'traceback': traceback.format_exc(),
                'task_type': self.task_type,
            }

    def _detect_task_type(self) -> str:
        model = self._model
        name = type(model).__name__.lower()
        if 'classifier' in name:
            return 'classification'
        if 'regressor' in name:
            return 'regression'
        if 'cluster' in name:
            return 'clustering'
        # Check attributes
        if hasattr(model, 'classes_'):
            return 'classification'
        if hasattr(model, 'n_clusters'):
            return 'clustering'
        return 'unknown'

    def _format_output(self, result) -> dict[str, Any]:
        """Convert numpy/primitive result to JSON-serializable."""
        raw = None
        prediction = None

        if isinstance(result, np.ndarray):
            raw = result.tolist()
            if result.ndim == 0:
                prediction = str(result.item())
            elif result.ndim == 1:
                if self._class_labels and len(self._class_labels) == len(result):
                    # Probabilities — label each one
                    prediction = [
                        dict(label=str(self._class_labels[i]), score=float(v))
                        for i, v in enumerate(result)
                    ]
                else:
                    prediction = raw[0] if len(raw) == 1 else raw
            else:
                prediction = raw
        elif isinstance(result, (list, tuple)):
            raw = list(result)
            prediction = raw[0] if len(raw) == 1 else raw
        else:
            raw = result
            prediction = result

        # If we have class labels and result is a single int/string
        if self._class_labels and isinstance(prediction, (int, np.integer)):
            idx = int(prediction)
            if 0 <= idx < len(self._class_labels):
                prediction = str(self._class_labels[idx])

        return {'prediction': prediction, 'raw': raw}

/**
 * ModelForge API Client
 * Shared JavaScript for all frontend pages
 */

const API_BASE = '/api';

const api = {
  // ── Models ────────────────────────────────────────────────────────────────
  async listModels() {
    const res = await fetch(`${API_BASE}/models`);
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  async uploadModel(formData) {
    const res = await fetch(`${API_BASE}/upload`, {
      method: 'POST',
      body: formData,
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }));
      throw new Error(err.detail || res.statusText);
    }
    return res.json();
  },

  async deleteModel(modelId) {
    const res = await fetch(`${API_BASE}/models/${modelId}`, { method: 'DELETE' });
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  // ── API Keys ───────────────────────────────────────────────────────────────
  async listKeys(modelId) {
    const res = await fetch(`${API_BASE}/keys?model_id=${encodeURIComponent(modelId)}`);
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  async createKey(modelId, purpose, label) {
    const res = await fetch(`${API_BASE}/keys`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model_id: modelId, purpose, label }),
    });
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  async revokeKey(keyId) {
    const res = await fetch(`${API_BASE}/keys/${keyId}`, { method: 'DELETE' });
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  // ── Predictions ────────────────────────────────────────────────────────────
  async predict(modelId, data, apiKey) {
    const res = await fetch(`${API_BASE}/predict/${modelId}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': apiKey,
      },
      body: JSON.stringify({ data }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }));
      throw new Error(err.detail || res.statusText);
    }
    return res.json();
  },

  // ── Dashboard ───────────────────────────────────────────────────────────────
  async getStats() {
    const res = await fetch(`${API_BASE}/dashboard`);
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },

  async getLogs(modelId, limit = 100) {
    const res = await fetch(`${API_BASE}/logs/${modelId}?limit=${limit}`);
    if (!res.ok) throw new Error(await res.text());
    return res.json();
  },
};

// ── Utility helpers ────────────────────────────────────────────────────────────

function formatBytes(bytes) {
  if (!bytes) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}

function timeAgo(isoString) {
  if (!isoString) return '';
  const diff = Date.now() - new Date(isoString).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

function copyToClipboard(text) {
  navigator.clipboard.writeText(text).then(() => {
    showToast('Copied to clipboard!');
  }).catch(() => {
    // Fallback
    const ta = document.createElement('textarea');
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast('Copied to clipboard!');
  });
}

let _toastTimeout = null;
function showToast(message, type = 'success') {
  let toast = document.querySelector('.mf-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.className = 'mf-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.className = `mf-toast mf-toast-${type} mf-toast-visible`;
  clearTimeout(_toastTimeout);
  _toastTimeout = setTimeout(() => {
    toast.classList.remove('mf-toast-visible');
  }, 3000);
}

// ── Toast styles ──────────────────────────────────────────────────────────────
const toastStyle = document.createElement('style');
toastStyle.textContent = `
  .mf-toast {
    position: fixed;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%) translateY(100px);
    background: #22c55e;
    color: #fff;
    padding: 12px 28px;
    border-radius: 50px;
    font-family: 'Space Grotesk', sans-serif;
    font-size: 0.9rem;
    font-weight: 600;
    z-index: 99999;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    pointer-events: none;
    box-shadow: 0 8px 30px rgba(0,0,0,0.3);
    white-space: nowrap;
  }
  .mf-toast.mf-toast-error { background: #ef4444; }
  .mf-toast.mf-toast-visible { transform: translateX(-50%) translateY(0); }
`;
document.head.appendChild(toastStyle);

