/* ═══════════════════════════════════════════════════════════════════════════
   ModelForge — Styles
   Scroll-driven, cinematic landing page with video-like sections
═══════════════════════════════════════════════════════════════════════════ */

/* ── Reset & Base ─────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:         #05050f;
  --bg2:        #080818;
  --surface:    #0f0f24;
  --surface2:   #16162e;
  --border:     rgba(99, 102, 241, 0.15);
  --border2:    rgba(99, 102, 241, 0.3);
  --primary:    #6366f1;
  --primary-d:  #4f46e5;
  --accent:     #a855f7;
  --accent2:    #ec4899;
  --cyan:       #22d3ee;
  --green:      #22c55e;
  --text:       #e2e8f0;
  --text-dim:   #94a3b8;
  --text-muted: #475569;
  --font:       'Space Grotesk', system-ui, sans-serif;
  --mono:       'JetBrains Mono', monospace;
  --radius:     12px;
  --radius-lg:  20px;
  --shadow:     0 0 60px rgba(99,102,241,0.08);
  --glow:       0 0 80px rgba(99,102,241,0.12);
}

html {
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: var(--primary) var(--surface);
}

::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--surface); }
::-webkit-scrollbar-thumb { background: var(--primary); border-radius: 3px; }

::selection { background: rgba(99,102,241,0.4); color: #fff; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; }
button { cursor: pointer; font-family: var(--font); }

/* ── Utility ──────────────────────────────────────────────────────────────── */
.gradient-text {
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 50%, var(--accent2) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.highlight { color: var(--accent2); font-style: italic; }

/* ── Buttons ──────────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  border-radius: 50px;
  font-size: 0.9rem;
  font-weight: 600;
  font-family: var(--font);
  border: none;
  transition: all 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
  cursor: pointer;
  white-space: nowrap;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: #fff;
  box-shadow: 0 4px 20px rgba(99,102,241,0.35);
}
.btn-primary:hover {
  transform: translateY(-2px) scale(1.03);
  box-shadow: 0 8px 30px rgba(99,102,241,0.5);
}
.btn-primary:active { transform: translateY(0) scale(0.98); }

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1.5px solid var(--border2);
}
.btn-outline:hover {
  background: rgba(99,102,241,0.1);
  border-color: var(--primary);
  transform: translateY(-2px);
}

.btn-ghost {
  background: transparent;
  color: var(--text-dim);
  border: none;
}
.btn-ghost:hover { color: var(--text); }

.btn-lg { padding: 14px 30px; font-size: 1rem; }

/* ── Scroll Progress Bar ──────────────────────────────────────────────────── */
.scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--primary), var(--accent), var(--accent2));
  width: 0%;
  z-index: 1000;
  transition: width 0.1s linear;
  box-shadow: 0 0 10px rgba(168,85,247,0.5);
}

/* ── Navigation ───────────────────────────────────────────────────────────── */
.mf-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 999;
  background: rgba(5,5,15,0.7);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
  transition: background 0.3s;
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.15rem;
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  gap: 28px;
  margin-left: auto;
}
.nav-links a {
  color: var(--text-dim);
  font-size: 0.88rem;
  font-weight: 500;
  transition: color 0.2s;
}
.nav-links a:hover { color: var(--text); }

.nav-actions { display: flex; gap: 12px; }

/* ── Section Layout ───────────────────────────────────────────────────────── */
.section-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-label {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 16px;
  padding: 6px 16px;
  border: 1px solid var(--border2);
  border-radius: 50px;
  background: rgba(99,102,241,0.08);
}

.section-title {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.section-desc {
  font-size: 1.1rem;
  color: var(--text-dim);
  max-width: 600px;
  line-height: 1.7;
}

/* ── HERO SECTION ─────────────────────────────────────────────────────────── */
.hero-section {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 100px 24px 80px;
  overflow: hidden;
  text-align: center;
}

/* Animated grid background */
.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(99,102,241,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(99,102,241,0.06) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 40%, black 0%, transparent 70%);
  animation: gridPulse 8s ease-in-out infinite;
}

@keyframes gridPulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 1; }
}

/* Particles */
.particles {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.particle {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
  opacity: 0;
  animation: particleFloat var(--duration) ease-in-out var(--delay) infinite;
}
@keyframes particleFloat {
  0% { transform: translateY(100vh) scale(0); opacity: 0; }
  10% { opacity: 0.6; }
  90% { opacity: 0.6; }
  100% { transform: translateY(-20vh) scale(1); opacity: 0; }
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 860px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 18px;
  border-radius: 50px;
  border: 1px solid rgba(168,85,247,0.3);
  background: rgba(168,85,247,0.08);
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 32px;
}
.badge-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
  animation: badgePulse 2s ease-in-out infinite;
}
@keyframes badgePulse {
  0%, 100% { box-shadow: 0 0 6px var(--green); }
  50% { box-shadow: 0 0 16px var(--green), 0 0 30px var(--green); }
}

.hero-title {
  font-size: clamp(2.8rem, 7vw, 5.5rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.04em;
  margin-bottom: 28px;
}
.title-line {
  display: block;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-dim);
  line-height: 1.7;
  margin-bottom: 40px;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 64px;
}

.hero-stats {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-number {
  font-size: 2.2rem;
  font-weight: 700;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.stat-unit {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--accent);
  -webkit-text-fill-color: var(--accent);
}
.stat-label {
  display: block;
  font-size: 0.78rem;
  color: var(--text-muted);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.stat-divider {
  width: 1px;
  height: 40px;
  background: var(--border);
}

/* Hero Code Window */
.hero-code {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 680px;
  margin-top: 60px;
}

.code-window {
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--glow), 0 20px 60px rgba(0,0,0,0.4);
  text-align: left;
}
.code-titlebar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 18px;
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}
.dot.red    { background: #ef4444; }
.dot.yellow { background: #f59e0b; }
.dot.green  { background: #22c55e; }
.code-filename {
  margin-left: 12px;
  font-size: 0.8rem;
  font-family: var(--mono);
  color: var(--text-muted);
}
.code-body {
  padding: 24px;
  font-family: var(--mono);
  font-size: 0.85rem;
  line-height: 1.8;
  overflow-x: auto;
  background: linear-gradient(180deg, rgba(99,102,241,0.03) 0%, transparent 100%);
}
.code-body code { color: var(--text-dim); }
.c-comment { color: var(--text-muted); }
.c-keyword { color: var(--cyan); }
.c-fn      { color: var(--accent2); }
.c-str     { color: #86efac; }

/* Scroll indicator */
.scroll-indicator {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  color: var(--text-muted);
  font-weight: 500;
  letter-spacing: 0.08em;
  animation: scrollBounce 2s ease-in-out infinite;
}
@keyframes scrollBounce {
  0%, 100% { transform: translateX(-50%) translateY(0); }
  50% { transform: translateX(-50%) translateY(8px); }
}
.scroll-mouse {
  width: 22px;
  height: 36px;
  border: 2px solid var(--text-muted);
  border-radius: 11px;
  display: flex;
  justify-content: center;
  padding-top: 6px;
}
.scroll-wheel {
  width: 3px;
  height: 8px;
  background: var(--text-muted);
  border-radius: 2px;
  animation: scrollWheel 2s ease-in-out infinite;
}
@keyframes scrollWheel {
  0% { opacity: 1; transform: translateY(0); }
  100% { opacity: 0; transform: translateY(10px); }
}

/* ── PROBLEM SECTION ───────────────────────────────────────────────────────── */
.problem-section {
  padding: 140px 0;
  background: var(--bg2);
  position: relative;
}
.problem-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--border2), transparent);
}

.pain-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
  margin-top: 56px;
}

.pain-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.pain-card:hover {
  border-color: rgba(239,68,68,0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(239,68,68,0.08);
}
.pain-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: rgba(239,68,68,0.1);
  border: 1px solid rgba(239,68,68,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: #ef4444;
}
.pain-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
  color: var(--text);
}
.pain-card p {
  font-size: 0.9rem;
  color: var(--text-dim);
  line-height: 1.65;
}

/* ── SOLUTION SECTION ────────────────────────────────────────────────────── */
.solution-section {
  padding: 140px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.solution-bg-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 40% at 50% 0%, rgba(99,102,241,0.12) 0%, transparent 60%),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(168,85,247,0.08) 0%, transparent 60%),
    radial-gradient(ellipse 40% 40% at 80% 60%, rgba(236,72,153,0.06) 0%, transparent 60%);
  pointer-events: none;
}
.solution-section .section-title { margin-bottom: 16px; }
.solution-section .section-desc { margin: 0 auto; }

/* ── FEATURES SECTION ─────────────────────────────────────────────────────── */
.features-section {
  padding: 140px 0;
  background: var(--bg2);
}
.features-section .section-title { margin-bottom: 56px; }

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}

.feature-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  overflow: hidden;
  transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.feature-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(99,102,241,0.05) 0%, transparent 60%);
  pointer-events: none;
}
.feature-card:hover {
  border-color: var(--primary);
  transform: translateY(-5px);
  box-shadow: 0 16px 50px rgba(99,102,241,0.12);
}
.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, rgba(99,102,241,0.15), rgba(168,85,247,0.1));
  border: 1px solid var(--border2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--primary);
}
.feature-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 10px;
}
.feature-card p {
  font-size: 0.88rem;
  color: var(--text-dim);
  line-height: 1.65;
  margin-bottom: 16px;
}
.feature-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 50px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: rgba(99,102,241,0.12);
  color: var(--primary);
  border: 1px solid rgba(99,102,241,0.2);
}

/* ── HOW IT WORKS SECTION ─────────────────────────────────────────────────── */
.how-section {
  padding: 140px 0;
}
.how-section .section-title { margin-bottom: 72px; }

.steps-container {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.step-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 32px;
  align-items: flex-start;
  position: relative;
  padding-bottom: 60px;
}
.step-item:last-child { padding-bottom: 0; }

.step-number {
  font-size: 3.5rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
  padding-top: 8px;
  opacity: 0.3;
}

.step-connector {
  position: absolute;
  left: 39px;
  top: 80px;
  width: 2px;
  height: calc(100% - 80px);
  background: linear-gradient(180deg, var(--border2), transparent);
}

.step-content h3 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 12px;
}
.step-content p {
  color: var(--text-dim);
  font-size: 0.95rem;
  line-height: 1.7;
  margin-bottom: 20px;
  max-width: 560px;
}
.step-icon {
  width: 72px;
  height: 72px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, rgba(99,102,241,0.15), rgba(168,85,247,0.1));
  border: 1px solid var(--border2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  color: var(--accent);
}

.step-code {
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: var(--radius);
  overflow: hidden;
}
.step-code pre {
  padding: 16px 20px;
  font-family: var(--mono);
  font-size: 0.8rem;
  color: var(--text-dim);
  line-height: 1.7;
  overflow-x: auto;
}
.step-code code { color: var(--text-dim); }

/* ── DEMO SECTION ─────────────────────────────────────────────────────────── */
.demo-section {
  padding: 140px 0;
  background: var(--bg2);
}
.demo-section .section-title { margin-bottom: 12px; }
.demo-section .section-desc { margin-bottom: 48px; }

.demo-console {
  max-width: 800px;
  margin: 0 auto;
}

.demo-window {
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--glow), 0 20px 60px rgba(0,0,0,0.3);
}
.demo-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
}
.demo-dots { display: flex; gap: 6px; }
.demo-dots .dot { width: 11px; height: 11px; }
.demo-title {
  font-size: 0.82rem;
  font-family: var(--mono);
  color: var(--text-muted);
  margin-left: 4px;
}
.demo-badge {
  margin-left: auto;
  padding: 3px 10px;
  border-radius: 50px;
  font-size: 0.7rem;
  font-weight: 700;
  background: rgba(34,197,94,0.15);
  color: var(--green);
  border: 1px solid rgba(34,197,94,0.3);
  letter-spacing: 0.06em;
  animation: livePulse 2s ease-in-out infinite;
}
@keyframes livePulse {
  0%, 100% { box-shadow: 0 0 6px rgba(34,197,94,0.3); }
  50% { box-shadow: 0 0 14px rgba(34,197,94,0.5); }
}

.demo-body { padding: 24px; }

.demo-input-area label {
  display: block;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 10px;
}
.demo-input-area textarea {
  width: 100%;
  background: var(--bg2);
  border: 1px solid var(--border2);
  border-radius: var(--radius);
  padding: 16px;
  color: var(--text);
  font-family: var(--font);
  font-size: 0.9rem;
  resize: vertical;
  transition: border-color 0.2s;
  line-height: 1.6;
}
.demo-input-area textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
}
.demo-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  flex-wrap: wrap;
  gap: 12px;
}
.demo-key-display {
  display: flex;
  align-items: center;
  gap: 10px;
}
.key-label { font-size: 0.8rem; color: var(--text-muted); font-weight: 600; }
.key-value {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--accent);
  background: rgba(168,85,247,0.1);
  padding: 4px 12px;
  border-radius: 6px;
  border: 1px solid rgba(168,85,247,0.2);
}

.demo-output {
  margin-top: 20px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-height: 100px;
  max-height: 280px;
  overflow-y: auto;
  transition: all 0.3s;
}
.demo-output-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100px;
  color: var(--text-muted);
  gap: 8px;
}
.demo-output-placeholder p { font-size: 0.85rem; }

.demo-result {
  padding: 20px;
  font-family: var(--mono);
  font-size: 0.85rem;
  line-height: 1.7;
  animation: resultReveal 0.4s ease-out;
}
@keyframes resultReveal {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.demo-result-error { color: #ef4444; }
.result-label { color: var(--text-muted); }
.result-value { color: var(--text); }
.result-success { color: var(--green); font-weight: 700; }
.result-spam { color: #ef4444; font-weight: 700; }
.result-ham { color: var(--green); font-weight: 700; }

/* ── CTA SECTION ─────────────────────────────────────────────────────────── */
.cta-section {
  padding: 140px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 50% at 50% 50%, rgba(99,102,241,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.cta-content { position: relative; z-index: 1; }
.cta-content h2 {
  font-size: clamp(2rem, 4vw, 3.2rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}
.cta-content p {
  color: var(--text-dim);
  font-size: 1.05rem;
  margin-bottom: 36px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}
.cta-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ── Footer ───────────────────────────────────────────────────────────────── */
.mf-footer {
  padding: 48px 24px;
  border-top: 1px solid var(--border);
  background: var(--surface);
}
.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}
.footer-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  font-size: 1rem;
}
.footer-copy {
  font-size: 0.82rem;
  color: var(--text-muted);
  margin-left: auto;
}
.footer-links {
  display: flex;
  gap: 20px;
  margin-left: 32px;
}
.footer-links a {
  font-size: 0.82rem;
  color: var(--text-muted);
  transition: color 0.2s;
}
.footer-links a:hover { color: var(--text); }

/* ── Scroll Reveal Animations ─────────────────────────────────────────────── */
/* Items start invisible, GSAP animates them in */
.reveal-item,
.reveal-card {
  opacity: 0;
  transform: translateY(40px);
}

/* ── Dashboard Page Styles ────────────────────────────────────────────────── */
.page-container {
  padding-top: 100px;
  padding-bottom: 80px;
  min-height: 100vh;
}
.page-header {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px 48px;
}
.page-title {
  font-size: 2.4rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.page-subtitle { color: var(--text-dim); font-size: 1rem; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all 0.3s;
}
.stat-card:hover {
  border-color: var(--primary);
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(99,102,241,0.1);
}
.stat-card-label {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 8px;
}
.stat-card-value {
  font-size: 2.2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.stat-card-sub { font-size: 0.8rem; color: var(--text-muted); margin-top: 4px; }

.section-block {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 28px;
}
.section-block-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.section-block-title {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
}
.section-block-body { padding: 0; }

/* Model Cards */
.models-list { display: flex; flex-direction: column; gap: 0; }
.model-card-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--border);
  transition: background 0.2s;
}
.model-card-item:last-child { border-bottom: none; }
.model-card-item:hover { background: rgba(99,102,241,0.04); }
.model-card-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(99,102,241,0.15), rgba(168,85,247,0.1));
  border: 1px solid var(--border2);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--primary);
}
.model-card-info { flex: 1; min-width: 0; }
.model-card-name {
  font-weight: 700;
  font-size: 0.95rem;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.model-card-meta {
  font-size: 0.78rem;
  color: var(--text-muted);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.model-card-badge {
  padding: 2px 10px;
  border-radius: 50px;
  font-size: 0.72rem;
  font-weight: 600;
  background: rgba(99,102,241,0.12);
  color: var(--primary);
  border: 1px solid rgba(99,102,241,0.2);
  text-transform: capitalize;
}
.model-card-actions { display: flex; gap: 8px; flex-shrink: 0; }

/* Log table */
.log-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
.log-table th {
  padding: 12px 16px;
  text-align: left;
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  background: var(--surface2);
  border-bottom: 1px solid var(--border);
}
.log-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-dim);
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.log-table tr:last-child td { border-bottom: none; }
.log-table tr:hover td { background: rgba(99,102,241,0.03); }
.log-success { color: var(--green); }
.log-error { color: #ef4444; }
.log-time { color: var(--text-muted); font-family: var(--mono); font-size: 0.78rem; }
.log-input {
  font-family: var(--mono);
  font-size: 0.78rem;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: block;
}

/* Empty state */
.empty-state {
  padding: 64px 24px;
  text-align: center;
  color: var(--text-muted);
}
.empty-state-icon {
  margin: 0 auto 16px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(99,102,241,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
}
.empty-state h3 { font-size: 1.1rem; font-weight: 700; color: var(--text); margin-bottom: 8px; }
.empty-state p { font-size: 0.88rem; }

/* ── Upload Page ──────────────────────────────────────────────────────────── */
.upload-container {
  max-width: 680px;
  margin: 0 auto;
  padding: 0 24px;
}
.upload-dropzone {
  border: 2px dashed var(--border2);
  border-radius: var(--radius-lg);
  padding: 64px 32px;
  text-align: center;
  transition: all 0.3s;
  cursor: pointer;
  background: var(--surface);
}
.upload-dropzone:hover,
.upload-dropzone.drag-over {
  border-color: var(--primary);
  background: rgba(99,102,241,0.06);
  box-shadow: 0 0 40px rgba(99,102,241,0.1);
}
.upload-dropzone-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(99,102,241,0.15), rgba(168,85,247,0.1));
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  color: var(--primary);
}
.upload-dropzone h3 { font-size: 1.2rem; font-weight: 700; margin-bottom: 8px; }
.upload-dropzone p { font-size: 0.88rem; color: var(--text-muted); }
.upload-dropzone .browse-link { color: var(--primary); font-weight: 600; }

.upload-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 24px;
}
.form-group { display: flex; flex-direction: column; gap: 8px; }
.form-label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.form-input, .form-select, .form-textarea {
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: var(--radius);
  padding: 12px 16px;
  color: var(--text);
  font-family: var(--font);
  font-size: 0.92rem;
  transition: all 0.2s;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.12);
}
.form-textarea { resize: vertical; line-height: 1.6; }
.form-hint { font-size: 0.78rem; color: var(--text-muted); }
.form-error {
  font-size: 0.78rem;
  color: #ef4444;
  background: rgba(239,68,68,0.1);
  border: 1px solid rgba(239,68,68,0.2);
  border-radius: 6px;
  padding: 10px 14px;
}

/* Upload result */
.upload-result {
  background: var(--surface);
  border: 1px solid rgba(34,197,94,0.3);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-top: 24px;
  animation: resultReveal 0.4s ease-out;
}
.upload-result.success { border-color: rgba(34,197,94,0.3); }
.upload-result h3 {
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 8px;
}
.upload-key-box {
  background: rgba(168,85,247,0.1);
  border: 1px solid rgba(168,85,247,0.2);
  border-radius: var(--radius);
  padding: 14px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
}
.upload-key-value {
  font-family: var(--mono);
  font-size: 0.85rem;
  color: var(--accent);
  word-break: break-all;
}
.btn-copy {
  background: rgba(168,85,247,0.15);
  border: 1px solid rgba(168,85,247,0.3);
  color: var(--accent);
  padding: 6px 14px;
  border-radius: 8px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}
.btn-copy:hover { background: rgba(168,85,247,0.25); }

/* ── API Keys Page ────────────────────────────────────────────────────────── */
.keys-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 28px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  align-items: flex-start;
}
@media (max-width: 720px) {
  .keys-layout { grid-template-columns: 1fr; }
}

.keys-sidebar {
  position: sticky;
  top: 88px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
}
.sidebar-title {
  font-size: 0.82rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.model-list-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.2s;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-dim);
  margin-bottom: 4px;
}
.model-list-item:hover { background: rgba(99,102,241,0.08); color: var(--text); }
.model-list-item.active {
  background: rgba(99,102,241,0.15);
  color: var(--primary);
  border: 1px solid rgba(99,102,241,0.2);
}
.model-list-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--primary);
  flex-shrink: 0;
}

.keys-main {}

.keys-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 20px;
}
.keys-header h2 { font-size: 1.4rem; font-weight: 700; }

.keys-list { display: flex; flex-direction: column; gap: 12px; }
.key-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
  transition: all 0.3s;
}
.key-card:hover { border-color: var(--border2); }
.key-card.revoked { opacity: 0.5; }
.key-info { flex: 1; min-width: 0; }
.key-label-text { font-weight: 700; font-size: 0.95rem; margin-bottom: 4px; }
.key-meta { font-size: 0.78rem; color: var(--text-muted); display: flex; gap: 16px; flex-wrap: wrap; }
.key-value-full {
  font-family: var(--mono);
  font-size: 0.82rem;
  color: var(--accent);
  background: rgba(168,85,247,0.08);
  border: 1px solid rgba(168,85,247,0.2);
  border-radius: 8px;
  padding: 8px 14px;
  word-break: break-all;
}
.key-actions { display: flex; gap: 8px; flex-shrink: 0; }

.btn-small {
  padding: 6px 14px;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: 8px;
  border: 1px solid var(--border2);
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
