  font-family: var(--font);
}
.btn-small:hover { background: rgba(99,102,241,0.1); color: var(--text); border-color: var(--primary); }
.btn-small.danger:hover { background: rgba(239,68,68,0.1); color: #ef4444; border-color: rgba(239,68,68,0.3); }

/* ── Loading spinner ──────────────────────────────────────────────────────── */
.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid rgba(255,255,255,0.2);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
  flex-shrink: 0;
