@keyframes spin { to { transform: rotate(360deg); } }

/* ── Predict Console (dashboard inline) ─────────────────────────────────── */
.predict-console {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.predict-console-header {
