def predict(self, data: Any) -> dict[str, Any]:
    """Run prediction. Returns dict with result, raw_output, metadata."""
    if self._model is None:
        raise RuntimeError("Model not loaded. Call load() first.")

    try:
        # Normalize input — preserve original data structure for sklearn pipelines
        if isinstance(data, list):
            if len(data) == 0:
                X = data
            elif isinstance(data[0], list):
                # 2D array (multiple samples, multiple features)
                X = np.array(data, dtype=float)
            elif isinstance(data[0], str):
                # Text data — pass as list of strings (sklearn vectorizers expect this)
                X = data
            else:
                # 1D numeric array — reshape if single sample
                arr = np.asarray(data, dtype=float)
                X = arr.reshape(1, -1) if arr.ndim == 1 else arr
        else:
            X = data

